const candidates = $input.all().map((item) => item.json);
const loadedAt = new Date().toISOString();
const rows = candidates.map((row) => ({
  fc_client_id: Number(row.fc_client_id),
  fc_client_name: row.fc_client_name,
  anchor_relationship_id: row.anchor_relationship_id,
  anchor_client_business_name: row.anchor_client_business_name,
  match_status: 'auto_exact',
  match_method: 'auto_exact',
  match_confidence: Number(row.match_confidence ?? 1),
  notes: 'Auto-loaded from profit_fc_client_anchor_match_candidates where match_status = auto_exact.',
  loaded_at: loadedAt,
}));
return [{
  json: {
    rows,
    summary: {
      candidateCount: candidates.length,
      upsertCount: rows.length,
      byMatchStatus: candidates.reduce((acc, row) => {
        const key = row.match_status ?? 'unknown';
        acc[key] = (acc[key] ?? 0) + 1;
        return acc;
      }, {}),
      samples: candidates.slice(0, 20),
    },
  },
}];

const built = $('Build FC Client Match Rows').first().json;
const protectedRows = $input.all().map((item) => item.json).filter((row) => row.fc_client_id);
const protectedIds = new Set(protectedRows.map((row) => Number(row.fc_client_id)));
const rows = built.rows.filter((row) => !protectedIds.has(Number(row.fc_client_id)));
return [{
  json: {
    rows,
    protectedManualOverrideCount: protectedIds.size,
    skippedManualOverrideSample: built.rows
      .filter((row) => protectedIds.has(Number(row.fc_client_id)))
      .slice(0, 20),
    summary: {
      ...built.summary,
      upsertCount: rows.length,
      protectedManualOverrideCount: protectedIds.size,
    },
  },
}];

const filtered = $('Filter Protected Manual Override Matches').first().json;
const upsertedRows = $('Upsert FC Client Anchor Matches').all().map((item) => item.json);
const reconcileItems = $('Reconcile Demoted FC Client Anchor Matches').all();
const reconcileRows = reconcileItems.map((item) => item.json).filter((row) => row && Object.keys(row).length > 0 && !row.error);
const reconcileErrorItem = reconcileItems.find((item) => item.json?.error || item.json?.message);
const reconcileError = reconcileErrorItem
  ? (reconcileErrorItem.json.error?.message ?? reconcileErrorItem.json.message ?? JSON.stringify(reconcileErrorItem.json))
  : null;

return [{
  json: {
    status: 'ok',
    upsertedFcClientMatchCount: upsertedRows.length,
    protectedManualOverrideCount: filtered.protectedManualOverrideCount,
    reconciledDemotedMatchCount: reconcileError ? 0 : reconcileRows.length,
    reconcileStatus: reconcileError ? 'error' : 'ok',
    reconcileError,
    sample: upsertedRows.slice(0, 20),
    skippedManualOverrideSample: filtered.skippedManualOverrideSample,
    reconciledSample: reconcileRows.slice(0, 20),
    note: 'Only unprotected auto_exact FC-to-Anchor client matches were upserted; manual override rows were preserved and demoted auto_exact rows were reconciled best-effort.',
  },
}];
